    // Check if the starting n-tersection coordinates are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        throw new IllegalArgumentException("Invalid starting n-tersection coordinates");
    }

    // Check if the ending n-tersection coordinates are valid
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        throw new IllegalArgumentException("Invalid ending n-tersection coordinates");
    }

    // Initialize the visited matrix to false
    boolean[][] visited = new boolean[n][n];

    // Initialize the queue with the starting n-tersection coordinates
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    // Label each n-tersection in the visited matrix as visited
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        visited[current[0]][current[1]] = true;

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Get the paths between adjacent n-tersections
        int[][] pathsFromCurrent = paths[current[0]][current[1]];

        // Add the paths that have not been visited to the queue
        for (int[] path : pathsFromCurrent) {
            if (!visited[path[0]][path[1]]) {
                queue.offer(path);
            }
        }
    }

    // If the ending n-tersection has not been visited, return "cannot be travelled"
    return "cannot be travelled";
