    if (n < 1) {
        throw new IllegalArgumentException("Invalid size of n");
    }

    // Check if the starting and ending n-tersection coordinates are valid
    if (start == null || end == null || start.length != n || end.length != n) {
        throw new IllegalArgumentException("Invalid starting or ending n-tersection coordinates");
    }

    // Check if the paths between adjacent n-tersections are valid
    if (paths == null || paths.length != n) {
        throw new IllegalArgumentException("Invalid paths between adjacent n-tersections");
    }
    for (int[] path : paths) {
        if (path == null || path.length != n) {
            throw new IllegalArgumentException("Invalid path between adjacent n-tersections");
        }
    }

    // Check if the starting n-tersection is the same as the ending n-tersection
    if (Arrays.equals(start, end)) {
        return "can be travelled";
    }

    // Check if the starting n-tersection is reachable from the ending n-tersection
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    Set<int[]> visited = new HashSet<>();
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (visited.contains(current)) {
            continue;
        }
        visited.add(current);
        for (int[] path : paths) {
            if (Arrays.equals(current, path)) {
                queue.offer(path);
            }
        }
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
    }

    // If the starting n-tersection cannot be reached from the ending n-tersection, return false
    return "cannot be travelled";
}
