public static String convertDatesToWeekdays(String date) {
    // Extract the parts of the date from the input
    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    // Create a calendar object for the given date
    Calendar cal = Calendar.getInstance();
    cal.set(Calendar.MONTH, month - 1); // month is 0-indexed
    cal.set(Calendar.DAY_OF_MONTH, day);
    cal.set(Calendar.YEAR, year);

    // Get the weekday of the date from the calendar object
    int weekday = cal.get(Calendar.DAY_OF_WEEK);

    // Create a mapping of weekday integers to weekday names
    Map<Integer, String> weekdays = new HashMap<>();
    weekdays.put(Calendar.SUNDAY, "Sunday");
    weekdays.put(Calendar.MONDAY, "Monday");
    weekdays.put(Calendar.TUESDAY, "Tuesday");
    weekdays.put(Calendar.WEDNESDAY, "Wednesday");
    weekdays.put(Calendar.THURSDAY, "Thursday");
    weekdays.put(Calendar.FRIDAY, "Friday");
    weekdays.put(Calendar.SATURDAY, "Saturday");

    // Get the weekday name from the mapping
    String weekdayName = weekdays.get(weekday);

    // Return the formatted string
    return "The date " + month + " " + day + " " + year + " is a " + weekdayName;
