public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a priority queue to store the nodes to visit
    PriorityQueue<Integer> queue = new PriorityQueue<>();

    // Initialize a hash map to store the distance from the starting node to each node
    Map<Integer, Integer> distances = new HashMap<>();

    // Initialize a hash map to store the boolean array indicating if a node has an apple
    Map<Integer, Boolean> hasApples = new HashMap<>();

    // Set the starting node to 0
    int startNode = 0;

    // Add the starting node to the queue
    queue.add(startNode);

    // Set the distance of the starting node to 0
    distances.put(startNode, 0);

    // Set the boolean array of the starting node to the input array
    hasApples.put(startNode, hasApple[startNode]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the node with the minimum distance from the queue
        int currentNode = queue.poll();

        // Loop through the edges of the current node
        for (int[] edge : edges) {
            // If the edge is not the starting node
            if (edge[0] != startNode) {
                // Get the other node of the edge
                int otherNode = edge[1];

                // If the other node is not already in the queue
                if (!queue.contains(otherNode)) {
                    // Add the other node to the queue and set its distance to the distance of the current node plus 1
                    queue.add(otherNode);
                    distances.put(otherNode, distances.get(currentNode) + 1);

                    // Set the boolean array of the other node to the input array
                    hasApples.put(otherNode, hasApple[otherNode]);
                }
            }
        }
    }

    // Initialize the minimum time to collect all the apples to infinity
    int minTime = Integer.MAX_VALUE;

    // Loop through the nodes in the hash map
    for (int node : distances.keySet()) {
        // If the current node has an apple
        if (hasApples.get(node)) {
            // Get the distance of the current node from the starting node
            int distance = distances.get(node);

            // If the distance is less than the minimum time
            if (distance < minTime) {
                // Set the minimum time to the distance
                minTime = distance;
            }
        }
    }

    // Return the minimum time to collect all the apples
    return minTime;
}
