public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create a queue to store the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();

    // Add the starting node (node 0) to the queue
    queue.add(0);

    // Create a visited array to keep track of the nodes that have already been visited
    boolean[] visited = new boolean[n];

    // Initialize the minimum time required to 0
    int minTime = 0;

    // Loop through the nodes in the queue
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int currentNode = queue.poll();

        // Check if the current node has an apple
        if (hasApple[currentNode]) {
            // Increment the minimum time required by 1
            minTime++;
        }

        // Loop through the edges of the current node
        for (int edge : edges[currentNode]) {
            // If the edge is not visited, add it to the queue
            if (!visited[edge]) {
                queue.add(edge);
                visited[edge] = true;
            }
        }
    }

    // Return the minimum time required
    return minTime;
}
