    visited[0] = true;
    queue.add(0);

    // Looping until the queue is empty
    while (!queue.isEmpty()) {
      // Getting the current node from the queue
      int currentNode = queue.remove();

      // Checking if the current node has an apple
      if (hasApple[currentNode]) {
        // Incrementing the minimum time by 2
        minTime += 2;
