      // Looping through the edges of the current node
      for (int[] edge : edges) {
        // Checking if the edge is valid and the destination node has not been visited
        if (edge[0] == currentNode && !visited[edge[1]]) {
          // Marking the destination node as visited and adding it to the queue
          visited[edge[1]] = true;
          queue.add(edge[1]);
        }
      }
    }

    // Returning the minimum time required to collect all the apples and return to node 0
