        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int current = 1;
                int x = i;
                int y = j;
                // Check horizontal line
                while (x < m - 1 && mat[x + 1][y] == 1) {
                    current++;
                    x++;
                }
                longest = Math.max(current, longest);
                // Check vertical line
                while (y < n - 1 && mat[x][y + 1] == 1) {
                    current++;
                    y++;
                }
                longest = Math.max(current, longest);
                // Check diagonal line
                while (x < m - 1 && y < n - 1 && mat[x + 1][y + 1] == 1) {
                    current++;
                    x++;
                    y++;
                }
                longest = Math.max(current, longest);
                // Check anti-diagonal line
                while (x > 0 && y > 0 && mat[x - 1][y - 1] == 1) {
                    current++;
                    x--;
                    y--;
                }
                longest = Math.max(current, longest);
